            WHERE
               c.compra_id=? and c.proveedor_id=p.proveedor_id and c.tipotrans_id=t.tipotrans_id and c.forma_id=f.forma_id and c.moneda_id=mo.moneda_id
        ",array($compra_id))->row_array();

        return $compra;
    }
    
